import collections,json
def f(g):
    H=len(g); W=len(g[0])
    twos=[(r,c) for r in range(H) for c in range(W) if g[r][c]==2]
    rs=collections.defaultdict(list); cs=collections.defaultdict(list)
    for r,c in twos: rs[r].append(c); cs[c].append(r)
    out=[[0]*W for _ in range(H)]
    # Case A: spine = row with >=2 dots (demo1/3 style). else no-spine demo2/4 case handled by the "hub" logic below.
    def hub_case(twos):
        hub=min(twos)
        C=hub[1]
        for d in sorted(twos):
            n=min([p for p in twos if p!=d], key=lambda q:(abs(q[0]-d[0]),abs(q[1]-d[1])))
            lo,hi=min(d[1],C),max(d[1],C)
            for cc in range(lo+1,hi):
                out[d[0]][cc]=3
            rr_lo,rr_hi=min(n[0],d[0]),max(n[0],d[0])
            for rr in range(rr_lo+1,rr_hi):
                out[rr][C]=3
        for r,c in twos:
            out[r][c]=2
        return out
    res=[]
    if any(len(v)>=2 for v in rs.values()):
        sr=max(rs.items(),key=lambda kv:(len(kv[1]),-kv[0]))[0]
        colds=sorted({c for r,c in twos})
        for c in range(min(colds),max(colds)+1):
            out[sr][c]=3 if out[sr][c]!=2 else 2
        for r,c in twos:
            if r==sr: continue
            for rr in range(min(r,sr)+1,max(r,sr)):
                out[rr][c]=3
        res=[out]
    else:
        res=[hub_case(twos)]
    return res[0]
