            same=[x for x in cs[c] if x!=r]
            # nearest dot (any direction) in this column; prefer one whose own segment passes through (e.g. its row on spine / it is a partner of someone on spine)
            def score(x):
                if len(cs[x])==1: return -1  # no partner, bad candidate
                return abs(x-r)
            cand=min(same,key=score) if same else None
            if cand is None:
                for x in range(min(r,sr)+1,max(r,sr)-1): out[x][c]=3
