                # actually fill between min and max of the two? check demo1 col7 pair (9,11) -> output fills 8..10 (from upper+1 to lower). So fill strictly between the two dots.
                lo,hi=(min(r,cand)+1,max(r,cand))
                for x in range(lo,hi): out[x][c]=3
    else:
        scol=max(cs.items(),key=lambda kv:(len(kv[1]),-kv[0]))[0]
        recs=sorted({r for r,c in pts})
        for r in range(min(recs),max(recs)+1):
            if any(p[1]==scol for p in pts): pass
            # connect each dot to scol horizontally; but only between extremes when multiple per row
        rows2d={}
        for r,c in pts: rows2d.setdefault(r,[]).append(c)
        for r in sorted(rows2d):
            cc=rows2d[r]
            if len(cc)>1: continue
            for cc in cc:
